import{_ as t,o,c as a,ag as d}from"./chunks/framework.HG0H2VLS.js";const g=JSON.parse('{"title":"ControlRecordScreen — token gaps","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/prototypes/ControlRecordScreen/ControlRecordScreen.token-gaps.md","filePath":"public/demos/src/prototypes/ControlRecordScreen/ControlRecordScreen.token-gaps.md"}'),r={name:"public/demos/src/prototypes/ControlRecordScreen/ControlRecordScreen.token-gaps.md"};function n(s,e,i,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="controlrecordscreen-—-token-gaps" tabindex="-1">ControlRecordScreen — token gaps <a class="header-anchor" href="#controlrecordscreen-—-token-gaps" aria-label="Permalink to &quot;ControlRecordScreen — token gaps&quot;">​</a></h1><p>Design owner&#39;s review list. Per <code>/build-prototype</code>, a value with no token is written raw and logged here rather than approximated to a near-miss token — a wrong binding survives re-tokenisation looking correct, an honest gap does not.</p><p>Audited by stripping comments from <code>ControlRecordScreen.css</code> and matching every declaration against <code>#hex</code>, <code>rgba()</code> and raw length units. <strong>No raw colour of any kind is used.</strong> Breakpoint values inside <code>@container</code> are excluded: CLAUDE.md §2 requires px literals there, not variables.</p><h2 id="genuine-gaps-—-3" tabindex="-1">Genuine gaps — 3 <a class="header-anchor" href="#genuine-gaps-—-3" aria-label="Permalink to &quot;Genuine gaps — 3&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Value</th><th>Selector</th><th>What it is for</th></tr></thead><tbody><tr><td><code>max-inline-size</code></td><td><code>78ch</code></td><td><code>.crs-field__value</code></td><td>A reading measure for long field values (Blog Intro, Summary, Page Description). Without it a 1440px screen hands the value column ~900px and the prose becomes unreadable. The <code>--ai-size-*</code> scale is px-only and the system has no <code>ch</code>/measure token at all — this is a genuinely missing concept, not a missing step.</td></tr><tr><td><code>height</code></td><td><code>72px</code></td><td><code>.crs-spark</code></td><td>Height of the impressions sparkline. Wanted a chart-height token; nearest are <code>--ai-spacing-10</code> (56px, too short to read a 12-point trend) and <code>--ai-size-1</code> (64px). <code>.chart__canvas</code> uses <code>min-height: 12rem</code> (192px) which is a full chart, not an inline spark.</td></tr><tr><td><code>max-height</code></td><td><code>480px</code></td><td><code>.crs-scroll</code></td><td>The 23-row Article Steps listing scrolls in place at roughly ten rows rather than running the page down. The <code>--ai-size-*</code> scale jumps 384 → 448 → 640; 448 shows nine rows and a clipped tenth, which reads as a rendering fault rather than a scroll affordance.</td></tr></tbody></table><h2 id="family-gap-—-1" tabindex="-1">Family gap — 1 <a class="header-anchor" href="#family-gap-—-1" aria-label="Permalink to &quot;Family gap — 1&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Token used</th><th>Where</th><th>The gap</th></tr></thead><tbody><tr><td><code>--ai-text-warning</code></td><td><code>.crs-advice__item [data-lucide]</code></td><td>The SEO-health advisory icons carry a warning colour, but <strong>there is no <code>--ai-icon-warning</code></strong>. The icon family has only <code>brand / contrast / primary / secondary / invert / invert-secondary</code> — no status slots at all, while text and surface both have the full five-status palette. Borrowing the text token is the least-wrong option available. <strong>This has a capture consequence:</strong> <code>scripts/gen-figma-rebind.mjs</code> picks a token family from node type, and a Lucide icon is a stroked vector, so it looks in <code>icon/*</code> — where this hex does not exist. Expect these three icons in <code>UNRESOLVED</code>. The fix is a design decision: either add status slots to the icon family, or rule that advisory icons are neutral and the status is carried by text alone.</td></tr></tbody></table><h2 id="binding-decisions-—-not-gaps-logged-so-the-reasoning-is-visible" tabindex="-1">Binding decisions — not gaps, logged so the reasoning is visible <a class="header-anchor" href="#binding-decisions-—-not-gaps-logged-so-the-reasoning-is-visible" aria-label="Permalink to &quot;Binding decisions — not gaps, logged so the reasoning is visible&quot;">​</a></h2><p>Both of these bind a real token that is a few px off the value discussed. Recording them because a near-miss binding is invisible afterwards — it looks like a considered choice either way, and the designer should get to disagree with it knowingly.</p><table tabindex="0"><thead><tr><th>Property</th><th>Bound to</th><th>Discussed</th><th>Note</th></tr></thead><tbody><tr><td><code>--crs-label-w</code></td><td><code>--ai-size-3</code> (192px)</td><td>~200px, measured off the v2 screen</td><td>Took the scale step rather than the measurement. 192 is what keeps the label gutter on the spacing system; 200 would be a raw value for an 8px gain.</td></tr><tr><td><code>--crs-aside-w</code> (model B)</td><td><code>--ai-size-7</code> (384px)</td><td>~420px</td><td>Scale has 384 and 448; 420 is neither. If the designer holds out for 420 it becomes a fourth genuine gap.</td></tr></tbody></table><h2 id="pre-approved-not-logged" tabindex="-1">Pre-approved, not logged <a class="header-anchor" href="#pre-approved-not-logged" aria-label="Permalink to &quot;Pre-approved, not logged&quot;">​</a></h2><p><code>1px</code> / <code>2px</code> border and underline widths — optical values, pre-approved by <code>/build-prototype</code>. Used on the card border, the card head rule, the fact-block border and the active tab underline.</p><hr><h2 id="measured-on-the-2026-09-22-push-step-6b-theme-cc" tabindex="-1">Measured on the 2026-09-22 push (step 6b, <code>--theme cc</code>) <a class="header-anchor" href="#measured-on-the-2026-09-22-push-step-6b-theme-cc" aria-label="Permalink to &quot;Measured on the 2026-09-22 push (step 6b, `--theme cc`)&quot;">​</a></h2><p>Six desktop frames, ~490 paints rebound to Semantic. <code>nonSemanticRemaining</code> is <strong>not</strong> 0 — the skill&#39;s target — because of the following, all left deliberately on their primitive and reported rather than guessed. A wrong semantic looks correct forever; a primitive at least looks wrong in dark mode.</p><table tabindex="0"><thead><tr><th>Unresolved</th><th>Count per frame</th><th>Whose</th><th>Verdict</th></tr></thead><tbody><tr><td><code>#CC4E00 as icon (currently orange/11)</code></td><td>9 (Article frames only)</td><td><strong>ours</strong></td><td><strong>The <code>--ai-icon-warning</code> gap above, confirmed by measurement.</strong> The CSS settles what it is — <code>.crs-advice__item [data-lucide] { color: var(--ai-text-warning) }</code> — but the rebind picks the family from node type, and a Lucide icon is a stroked vector, so it looks in <code>icon/*</code> where this hex does not exist. Deliberately NOT bound to <code>text/warning</code>: that would be a cross-family binding that pre-empts the design decision and then looks correct forever. Needs the designer&#39;s call.</td></tr><tr><td><code>#F3F6F7 as icon (currently MId Blue/100)</code></td><td>12</td><td>shell</td><td>SidebarMenu icons, inherited from the ControlScreen shell. Not this prototype&#39;s to resolve.</td></tr><tr><td><code>#000000 as border (unbound)</code></td><td>3–9</td><td>capture artefact</td><td>Default black border the serialiser emits; no token, nothing to bind.</td></tr><tr><td><code>#FFFFFF as surface (unbound)</code></td><td>1</td><td>ambiguous</td><td><code>#FFFFFF</code> is surface-primary, surface-elevated-1 AND surface-elevated-2. Un-overridable by value.</td></tr><tr><td><code>#0094AD as border (currently Lagoon/10)</code></td><td>1 (Article frames)</td><td>shell</td><td>The hex is <code>icon/brand</code>; there is no border token at it.</td></tr></tbody></table>',16)])])}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
